import HERO_CARDS from "./hero-cards.json"

/**
 * The example cards the landing hero rotates through, as generated by
 * svg-generator/scripts/generate-hero-cards.ts (files in public/hero).
 */
export interface HeroCard {
  slug: string
  width: number
  height: number
  plugins: string[]
}

export const HERO_CARD_LIST: readonly HeroCard[] = HERO_CARDS

/** How long each card stays: its entrance takes about 1.5 s, then it can be read. */
export const HERO_ROTATE_MS = 6000

/**
 * The frame reserves the tallest card's height, so the page under the hero and the copy
 * beside it do not move when a shorter card comes up.
 */
export const HERO_FRAME_HEIGHT = Math.max(...HERO_CARD_LIST.map((card) => card.height))

export const heroCardUrl = (card: HeroCard) => `/hero/${card.slug}.svg`

export const nextHeroIndex = (index: number) => (index + 1) % HERO_CARD_LIST.length
